-- release-target-preflight: migrationId=20260814_mes_production_release_roles; allowedEnvironments=test,prod,backup
-- Read-only original prerequisite/identity checks; no menu resurrection, grants, or fixture creation.
SELECT CASE WHEN
 (SELECT COUNT(*) FROM (SELECT u.tenant_id FROM system_users u JOIN system_tenant t ON t.id=u.tenant_id AND t.deleted=b'0' WHERE u.username IN('zhulijiang','xujianhai') AND u.status=0 AND u.deleted=b'0' GROUP BY u.tenant_id HAVING COUNT(DISTINCT u.username)=2 AND COUNT(*)=2) targets)=1
 AND NOT EXISTS(SELECT 1 FROM (SELECT u.tenant_id FROM system_users u JOIN system_tenant t ON t.id=u.tenant_id AND t.deleted=b'0' WHERE u.username IN('zhulijiang','xujianhai') AND u.status=0 AND u.deleted=b'0' GROUP BY u.tenant_id HAVING COUNT(DISTINCT u.username)=2 AND COUNT(*)=2) targets WHERE (SELECT COUNT(*) FROM system_role_category c WHERE c.tenant_id=targets.tenant_id AND c.code='menu' AND c.status=0 AND c.deleted=b'0')<>1)
 AND (SELECT COUNT(*) FROM system_menu WHERE permission='mes:pro-edhr-work-task:query' AND type=2 AND status=0 AND deleted=b'0')=1
 AND NOT EXISTS(SELECT 1 FROM system_role r WHERE r.tenant_id IN(SELECT u.tenant_id FROM system_users u JOIN system_tenant t ON t.id=u.tenant_id AND t.deleted=b'0' WHERE u.username IN('zhulijiang','xujianhai') AND u.status=0 AND u.deleted=b'0' GROUP BY u.tenant_id HAVING COUNT(DISTINCT u.username)=2 AND COUNT(*)=2) AND r.code IN('MES_PQC_RELEASE_OWNER','MES_MANAGEMENT_REPRESENTATIVE') GROUP BY tenant_id,code HAVING COUNT(*)>1)
 AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission IN('mes:pro-production-release:query','mes:pro-production-release:pqc-approve','mes:pro-production-release:pqc-reject') GROUP BY permission HAVING COUNT(*)>1)
 AND EXISTS(SELECT 1 FROM system_menu WHERE permission='mes:pro-edhr-release:query' AND status=0 AND deleted=b'0')
 AND EXISTS(SELECT 1 FROM system_menu WHERE permission='mes:pro-edhr-release:approve' AND status=0 AND deleted=b'0')
 AND (SELECT COUNT(*) FROM system_users WHERE tenant_id=1 AND ((id=1300 AND username='zhulijiang') OR (id=1524 AND username='xujianhai')) AND status=0 AND deleted=b'0')=2
 AND NOT EXISTS(SELECT 1 FROM system_users WHERE username IN('zhulijiang','xujianhai') AND status=0 AND deleted=b'0' AND NOT(tenant_id=1 AND ((id=1300 AND username='zhulijiang') OR (id=1524 AND username='xujianhai'))))
 AND NOT EXISTS(SELECT 1 FROM system_role r WHERE r.tenant_id=1 AND r.code IN('MES_PQC_RELEASE_OWNER','MES_MANAGEMENT_REPRESENTATIVE') AND (r.status<>0 OR r.deleted<>b'0' OR NOT COALESCE((r.code='MES_PQC_RELEASE_OWNER' AND r.name=CONVERT(UNHEX('505143E8B49FE8B4A3E4BABA') USING utf8mb4) COLLATE utf8mb4_unicode_ci) OR (r.code='MES_MANAGEMENT_REPRESENTATIVE' AND r.name=CONVERT(UNHEX('E7AEA1E79086E88085E4BBA3E8A1A8') USING utf8mb4) COLLATE utf8mb4_unicode_ci),FALSE)))
 AND NOT EXISTS(SELECT 1 FROM system_user_role ur JOIN system_role r ON r.id=ur.role_id AND r.tenant_id=1 WHERE r.code IN('MES_PQC_RELEASE_OWNER','MES_MANAGEMENT_REPRESENTATIVE') AND ur.deleted=b'0' AND NOT COALESCE(ur.tenant_id=1 AND ((r.code='MES_PQC_RELEASE_OWNER' AND ur.user_id=1300) OR (r.code='MES_MANAGEMENT_REPRESENTATIVE' AND ur.user_id=1524)),FALSE))
 AND NOT EXISTS(SELECT 1 FROM system_user_role ur JOIN system_role r ON r.id=ur.role_id AND r.tenant_id=1 WHERE r.code IN('MES_PQC_RELEASE_OWNER','MES_MANAGEMENT_REPRESENTATIVE') GROUP BY ur.user_id,ur.role_id HAVING COUNT(*)>1)
 THEN 'TARGET_PREFLIGHT_PASS:20260814_mes_production_release_roles' ELSE 'TARGET_PREFLIGHT_BLOCKED:20260814_mes_production_release_roles:MENU_ROLE_PREREQUISITE_OR_IDENTITY_CONFLICT' END;
